#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <limits>

// Jonker-Volgenant dense assignment. cost is row-major n*n.
// col_of_row[i] = assigned column.
extern "C" void lapjv_solve(const double* cost, int n, int* col_of_row) {
    const double BIG = 1e18;
    std::vector<double> v(n, 0.0), d(n);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> free_rows(n), new_free(n), pred(n), ready(n);
    std::vector<char> scanned(n);

    // column reduction reverse
    for (int j = n - 1; j >= 0; --j) {
        int imin = 0;
        double h = cost[j];
        for (int i = 1; i < n; ++i) {
            double c = cost[i * n + j];
            if (c < h) { h = c; imin = i; }
        }
        v[j] = h;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;

    for (int phase = 0; phase < 2 && nfree; ++phase) {
        int new_nfree = 0;
        for (int k = 0; k < nfree; ++k) {
            int i = free_rows[k];
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            const double* ci = cost + i * n;
            for (int j = 0; j < n; ++j) {
                double h = ci[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; j2 = j1; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && phase == 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0 && i0 != i) {
                rowsol[i0] = -1;
                new_free[new_nfree++] = i0;
            }
        }
        free_rows.swap(new_free);
        nfree = new_nfree;
    }

    // augmentation with linear scan (n=600, ~150 free -> ~150*600*avg_path)
    // Use a binary heap for Dijkstra.
    std::vector<double> hk(n * 8);
    std::vector<int> hc(n * 8);

    auto heap_sift_up = [&](int pos) {
        while (pos > 0) {
            int parent = (pos - 1) >> 1;
            if (hk[pos] < hk[parent]) {
                std::swap(hk[pos], hk[parent]);
                std::swap(hc[pos], hc[parent]);
                pos = parent;
            } else break;
        }
    };
    auto heap_sift_down = [&](int hsz, int i0) {
        while (true) {
            int l = i0 * 2 + 1, r = l + 1, s = i0;
            if (l < hsz && hk[l] < hk[s]) s = l;
            if (r < hsz && hk[r] < hk[s]) s = r;
            if (s == i0) break;
            std::swap(hk[i0], hk[s]);
            std::swap(hc[i0], hc[s]);
            i0 = s;
        }
    };

    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* cfr = cost + freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = cfr[j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int hsz = n;
        for (int j = 0; j < n; ++j) { hk[j] = d[j]; hc[j] = j; }
        for (int idx = n / 2 - 1; idx >= 0; --idx) heap_sift_down(hsz, idx);

        int nready = 0;
        int last = -1;
        double mind = 0;
        while (hsz > 0) {
            mind = hk[0];
            int jmin = hc[0];
            --hsz;
            hk[0] = hk[hsz];
            hc[0] = hc[hsz];
            heap_sift_down(hsz, 0);
            if (scanned[jmin]) continue;
            if (mind > d[jmin] + 1e-12) continue;
            scanned[jmin] = 1;
            ready[nready++] = jmin;
            int i = colsol[jmin];
            if (i < 0) { last = jmin; break; }
            double ui = cost[i * n + jmin] - v[jmin];
            double base = mind - ui;
            const double* ci = cost + i * n;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j]) {
                    double h = ci[j] - v[j] + base;
                    if (h < d[j]) {
                        d[j] = h;
                        pred[j] = i;
                        hk[hsz] = h;
                        hc[hsz] = j;
                        heap_sift_up(hsz);
                        ++hsz;
                    }
                }
            }
        }
        for (int k = 0; k < nready; ++k) {
            int j = ready[k];
            v[j] += d[j] - mind;
        }
        while (true) {
            int i = pred[last];
            colsol[last] = i;
            int jnext = rowsol[i];
            rowsol[i] = last;
            if (i == freerow) break;
            last = jnext;
        }
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = rowsol[i];
}
