import ctypes, numpy as np, time, ot
from scipy.spatial.distance import cdist
lib = ctypes.CDLL("./liblapjv.so")
lib.lapjv_solve.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int)]

def solve(M):
    n = M.shape[0]
    Mc = np.ascontiguousarray(M, dtype=np.float64)
    out = np.empty(n, dtype=np.int32)
    lib.lapjv_solve(Mc.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n, out.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return out

for n in (50, 200, 600):
    np.random.seed(1)
    M = cdist(np.random.rand(n,2), np.random.rand(n,2))
    t0=time.perf_counter(); cols=solve(M); t1=time.perf_counter()
    a=np.full(n,1/n)
    G=ot.lp.emd(a,a,np.ascontiguousarray(M),check_marginals=False)
    t2=time.perf_counter()
    exp=np.array([np.flatnonzero(G[i]>1e-12)[0] for i in range(n)], dtype=np.int32)
    print(n, "cpp", round(t1-t0,4), "emd", round(t2-t1,4), "speedup", round((t2-t1)/(t1-t0),2), "err", int(np.max(np.abs(cols-exp))))
