import numpy as np, ot
from collections import defaultdict

def network_simplex(a, b, M, enter_rule="first", leave_rule="first", max_pivots=100000, u0=0):
    a = np.asarray(a, np.float64).copy()
    b = np.asarray(b, np.float64).copy()
    b *= a.sum()/b.sum()
    n, m = M.shape
    basis_set = set()
    flow = {}
    i = j = 0
    aa = a.copy(); bb = b.copy()
    while len(basis_set) < n + m - 1:
        if i >= n or j >= m:
            break
        take = min(aa[i], bb[j])
        if (i, j) not in basis_set:
            basis_set.add((i, j))
        flow[(i, j)] = flow.get((i, j), 0.0) + take
        aa[i] -= take
        bb[j] -= take
        row_done = aa[i] <= 1e-12
        col_done = bb[j] <= 1e-12
        if row_done and col_done:
            if i < n-1 and j < m-1:
                i += 1
                if (i, j) not in basis_set and len(basis_set) < n+m-1:
                    basis_set.add((i, j))
                    flow.setdefault((i, j), 0.0)
                j += 1
            elif i < n-1:
                i += 1
            elif j < m-1:
                j += 1
            else:
                break
        elif row_done:
            i += 1
        else:
            j += 1
    if len(basis_set) != n+m-1:
        return None, -len(basis_set), False

    def build_adj():
        adj = defaultdict(list)
        for (ii, jj) in basis_set:
            adj[('r', ii)].append(('c', jj))
            adj[('c', jj)].append(('r', ii))
        return adj

    pivots = 0
    eps = 1e-9
    for _it in range(max_pivots):
        u = np.zeros(n)
        v = np.zeros(m)
        adj = build_adj()
        u_set = np.zeros(n, dtype=bool)
        v_set = np.zeros(m, dtype=bool)
        # root
        u[u0] = 0.0
        u_set[u0] = True
        stack = [('r', u0)]
        seen = {('r', u0)}
        while stack:
            node = stack.pop()
            for nei in adj[node]:
                if nei in seen: continue
                seen.add(nei)
                if node[0]=='r':
                    ii, jj = node[1], nei[1]
                    v[jj] = M[ii, jj] - u[ii]
                    v_set[jj] = True
                else:
                    jj, ii = node[1], nei[1]
                    u[ii] = M[ii, jj] - v[jj]
                    u_set[ii] = True
                stack.append(nei)
        if not (u_set.all() and v_set.all()):
            return None, pivots, False
        enter = None
        best = 0.0
        if enter_rule == "first":
            for ii in range(n):
                ui = u[ii]
                row = M[ii]
                for jj in range(m):
                    if (ii, jj) in basis_set: continue
                    if row[jj] - ui - v[jj] < -eps:
                        enter = (ii, jj); break
                if enter: break
        elif enter_rule == "most":
            for ii in range(n):
                ui = u[ii]
                row = M[ii]
                for jj in range(m):
                    if (ii, jj) in basis_set: continue
                    rc = row[jj] - ui - v[jj]
                    if rc < best - 1e-15:
                        best = rc; enter = (ii, jj)
        elif enter_rule == "colfirst":
            for jj in range(m):
                vj = v[jj]
                for ii in range(n):
                    if (ii, jj) in basis_set: continue
                    if M[ii, jj] - u[ii] - vj < -eps:
                        enter = (ii, jj); break
                if enter: break
        if enter is None:
            G = np.zeros((n, m))
            for (ii, jj), val in flow.items():
                if val > 1e-14:
                    G[ii, jj] = val
            return G, pivots, True
        # path
        start = ('r', enter[0]); goal = ('c', enter[1])
        parent = {start: None}
        st = [start]
        found = False
        while st:
            node = st.pop()
            if node == goal:
                found = True; break
            for nei in adj[node]:
                if nei not in parent:
                    parent[nei] = node
                    st.append(nei)
        if not found:
            return None, pivots, False
        path = []
        cur = goal
        while cur is not None:
            path.append(cur); cur = parent[cur]
        path.reverse()
        cycle = [(enter[0], enter[1], +1)]
        sign = -1
        for t in range(len(path)-1, 0, -1):
            A, B = path[t], path[t-1]
            if A[0]=='r':
                ii, jj = A[1], B[1]
            else:
                ii, jj = B[1], A[1]
            cycle.append((ii, jj, sign))
            sign = -sign
        # leaving
        theta = np.inf
        candidates = []
        for ii, jj, sgn in cycle:
            if sgn < 0:
                f = flow.get((ii, jj), 0.0)
                candidates.append((f, ii, jj))
        if not candidates:
            return None, pivots, False
        if leave_rule == "first":
            # first along reverse path (already order) with min flow, ties keep earliest
            theta = min(c[0] for c in candidates)
            leave = None
            for f, ii, jj in candidates:
                if f <= theta + 1e-12:
                    leave = (ii, jj); theta = f; break
            # recompute theta as that flow
            theta = flow.get(leave, 0.0)
        elif leave_rule == "min_index":
            theta = min(c[0] for c in candidates)
            tied = [(ii, jj) for f, ii, jj in candidates if f <= theta + 1e-12]
            leave = min(tied)  # smallest (i,j)
            theta = flow.get(leave, 0.0)
        elif leave_rule == "last":
            theta = min(c[0] for c in candidates)
            leave = None
            for f, ii, jj in candidates:
                if f <= theta + 1e-12:
                    leave = (ii, jj)
            theta = flow.get(leave, 0.0)
        for ii, jj, sgn in cycle:
            if sgn > 0:
                flow[(ii, jj)] = flow.get((ii, jj), 0.0) + theta
            else:
                flow[(ii, jj)] = max(0.0, flow.get((ii, jj), 0.0) - theta)
        basis_set.discard(leave)
        basis_set.add(enter)
        if flow.get(leave, 0) <= 1e-14:
            flow.pop(leave, None)
        pivots += 1
    return None, pivots, False

def check(n=8, seeds=8):
    rules = ["first", "most", "colfirst"]
    leaves = ["first", "min_index", "last"]
    for rule in rules:
        for leave in leaves:
            mismatches = 0
            fails = 0
            for s in range(seeds):
                rng = np.random.default_rng(s)
                a = np.full(n, 1/n)
                M = rng.random((n, n))
                Gref = ot.lp.emd(a, a, np.ascontiguousarray(M), check_marginals=False)
                G, piv, ok = network_simplex(a, a, M, enter_rule=rule, leave_rule=leave)
                if not ok:
                    fails += 1
                    continue
                if np.max(np.abs(G-Gref)) > 1e-6:
                    mismatches += 1
            print(f"rule={rule:10} leave={leave:10} mismatch {mismatches}/{seeds} fail {fails}")

check(6, 10)
