                    if M[ii, jj] - u[ii] - vj < -eps:
                        enter = (ii, jj); break
                if enter: break
        elif enter_rule == "block":
            # candidate block pivoting: all negative, but we still pick most negative among a random? skip
            pass
        if enter is None:
            G = np.zeros((n, m))
            for (ii, jj), val in flow.items():
                if val > 1e-12: G[ii, jj] = val
            return G, pivots, True
        start = ('r', enter[0]); goal = ('c', enter[1])
        parent = {start: None}; st = [start]
        while st:
            node = st.pop()
            if node == goal: break
            for nei in adj[node]:
                if nei not in parent:
                    parent[nei] = node; st.append(nei)
        path = []; cur = goal
        while cur is not None:
            path.append(cur); cur = parent[cur]
        path.reverse()
        cycle = [(enter[0], enter[1], +1)]
        sign = -1
        for t in range(len(path)-1, 0, -1):
            A, B = path[t], path[t-1]
            if A[0]=='r': ii, jj = A[1], B[1]
            else: ii, jj = B[1], A[1]
            cycle.append((ii, jj, sign)); sign = -sign
        cands = []
        for ii, jj, sgn in cycle:
            if sgn < 0:
                cands.append((flow.get((ii, jj), 0.0), ii, jj))
        if leave_rule == "first":
            theta = min(c[0] for c in cands)
            leave = next((ii, jj) for f, ii, jj in cands if f <= theta + 1e-12)
            theta = flow.get(leave, 0.0)
        elif leave_rule == "last":
            theta = min(c[0] for c in cands)
            leave = [(ii, jj) for f, ii, jj in cands if f <= theta + 1e-12][-1]
            theta = flow.get(leave, 0.0)
        elif leave_rule == "min_index":
            theta = min(c[0] for c in cands)
            tied = [(ii, jj) for f, ii, jj in cands if f <= theta + 1e-12]
            leave = min(tied)
            theta = flow.get(leave, 0.0)
        for ii, jj, sgn in cycle:
            if sgn > 0: flow[(ii, jj)] = flow.get((ii, jj), 0.0) + theta
            else: flow[(ii, jj)] = max(0.0, flow.get((ii, jj), 0.0) - theta)
        basis_set.discard(leave); basis_set.add(enter)
        if flow.get(leave, 0.0) <= 1e-14: flow.pop(leave, None)
        pivots += 1
    return None, pivots, False

def check(n=7, seeds=12):
    for rule in ("first", "most", "colfirst"):
        for leave in ("first", "last", "min_index"):
            mm = fl = 0
            for s in range(seeds):
                rng = np.random.default_rng(s+100)
                a = rng.random(n); a /= a.sum()
                b = rng.random(n); b = b * a.sum() / b.sum()
                M = rng.random((n, n))
                # introduce ties
                M = np.round(M, 2)
                Gref = ot.lp.emd(a, b, np.ascontiguousarray(M, np.float64), check_marginals=False)
                G, piv, ok = network_simplex(a, b, M, enter_rule=rule, leave_rule=leave)
                if not ok:
                    fl += 1; continue
                if np.max(np.abs(G - Gref)) > 1e-5:
                    mm += 1
            print(f"{rule:10} {leave:10} mismatch {mm}/{seeds} fail {fl}")

check()
