// Bertsekas auction, minimize cost. Returns col for each row.
extern "C" int auction_solve(const double* cost, int n, double eps, int max_iter, int* col_of_row) {
    const double NEG = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int nun = n;
    int it = 0;
    std::vector<double> values(n);
    while (nun > 0 && it < max_iter) {
        int i = unassigned[--nun];
        ++it;
        const double* ci = cost + (size_t)i * n;
        int jbest = 0;
        double best = NEG, second = NEG;
        for (int j = 0; j < n; ++j) {
            double val = -ci[j] - price[j];
            if (val > best) {
                second = best;
                best = val;
                jbest = j;
            } else if (val > second) {
                second = val;
            }
        }
        price[jbest] += (best - second) + eps;
        int prev = owner[jbest];
        owner[jbest] = i;
        assignment[i] = jbest;
        if (prev >= 0) {
            assignment[prev] = -1;
            unassigned[nun++] = prev;
        }
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return it;
}
