#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>

// Epsilon-scaling auction. Forward auction (rows bid).
extern "C" int auction_solve(const double* cost, int n, double eps_final, int* col_of_row) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);
    const double NEG = -1e300;

    // scale eps from max cost range down
    double cmax = 0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) if (cost[k] > cmax) cmax = cost[k];
    double eps = cmax / 4.0;
    if (eps < eps_final) eps = eps_final;
    int total_it = 0;

    while (true) {
        // reset assignment for this epsilon phase? Keep prices, restart assignment.
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int it = 0;
        int max_iter = n * 200;
        while (nun > 0 && it < max_iter) {
            int i = unassigned[--nun];
            ++it;
            const double* ci = cost + (size_t)i * n;
            int jbest = 0;
            double best = NEG, second = NEG;
            for (int j = 0; j < n; ++j) {
                double val = -ci[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            double inc = (best - second) + eps;
            if (inc < eps) inc = eps;
            price[jbest] += inc;
            int prev = owner[jbest];
            owner[jbest] = i;
            assignment[i] = jbest;
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned[nun++] = prev;
            }
        }
        total_it += it;
        if (eps <= eps_final * 1.0001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_it;
}
