#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>

// Fast Jonker-Volgenant with:
// - column reduction + reduction transfer + 2 augmenting row reduction passes
// - augmentation using a dense "todo" scan that skips scanned columns via a linked list of unscanned columns
extern "C" void jv_solve(const double* cost, int n, int* col_of_row) {
    const double BIG = 1e100;
    std::vector<double> v(n, 0.0), d(n), u(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> free_rows(n), pred(n), ready(n);
    std::vector<char> scanned(n);
    std::vector<int> prev_un(n), next_un(n);

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        int imin = 0;
        double h = cost[j];
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < h) { h = c; imin = i; }
        }
        v[j] = h;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
            u[imin] = cost[(size_t)imin * n + j] - v[j];
        }
    }
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;

    std::vector<int> new_free(n);
    for (int phase = 0; phase < 2 && nfree; ++phase) {
        int new_nfree = 0;
        for (int k = 0; k < nfree; ++k) {
            int i = free_rows[k];
            const double* ci = cost + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            for (int j = 0; j < n; ++j) {
                double h = ci[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; j2 = j1; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && phase == 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0 && i0 != i) {
                rowsol[i0] = -1;
                new_free[new_nfree++] = i0;
            }
        }
        free_rows.swap(new_free);
        nfree = new_nfree;
    }

    // augmentation
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* cfr = cost + (size_t)freerow * n;
        // doubly linked list of unscanned columns: 0..n-1
        for (int j = 0; j < n; ++j) {
            d[j] = cfr[j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
            prev_un[j] = j - 1;
            next_un[j] = j + 1;
        }
        next_un[n - 1] = -1;
        int head = 0; // first unscanned
        int nready = 0;
        int last = -1;
        double mind = 0;
        int unscanned = n;
        while (unscanned > 0) {
            // find min d among unscanned via linked list
            mind = BIG;
            int jmin = -1;
            for (int j = head; j >= 0; j = next_un[j]) {
                double dj = d[j];
                if (dj < mind) { mind = dj; jmin = j; }
            }
            // remove jmin from list
            int pj = prev_un[jmin], nj = next_un[jmin];
            if (pj >= 0) next_un[pj] = nj; else head = nj;
            if (nj >= 0) prev_un[nj] = pj;
            scanned[jmin] = 1;
            --unscanned;
            ready[nready++] = jmin;
            int i = colsol[jmin];
            if (i < 0) { last = jmin; break; }
            double ui = cost[(size_t)i * n + jmin] - v[jmin];
            double base = mind - ui;
            const double* ci = cost + (size_t)i * n;
            for (int j = head; j >= 0; j = next_un[j]) {
                double h = ci[j] - v[j] + base;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        for (int k = 0; k < nready; ++k) {
            int j = ready[k];
            v[j] += d[j] - mind;
        }
        while (true) {
            int i = pred[last];
            colsol[last] = i;
            int jnext = rowsol[i];
            rowsol[i] = last;
            if (i == freerow) break;
            last = jnext;
        }
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = rowsol[i];
}
