#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdint>
#include <cstring>

// Sparse epsilon-scaling auction.
// idxs: n*k int32 neighbor columns, dists: n*k double distances.
extern "C" int sparse_auction(const int* idxs, const double* dists, int n, int k,
                              double eps_final, int* col_of_row) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    std::vector<int> unassigned(n);
    double cmax = 0;
    for (int i = 0; i < n * k; ++i) if (dists[i] > cmax) cmax = dists[i];
    double eps = cmax / 4.0;
    if (eps < eps_final) eps = eps_final;
    int total_it = 0;
    const double NEG = -1e300;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int it = 0;
        int max_iter = n * 80;
        bool incomplete = false;
        while (nun > 0 && it < max_iter) {
            int i = unassigned[--nun];
            ++it;
            const int* js = idxs + (size_t)i * k;
            const double* ds = dists + (size_t)i * k;
            int jbest = js[0];
            double best = NEG, second = NEG;
            for (int t = 0; t < k; ++t) {
                double val = -ds[t] - price[js[t]];
                if (val > best) { second = best; best = val; jbest = js[t]; }
                else if (val > second) second = val;
            }
            if (second == NEG) second = best; // k==1
            price[jbest] += (best - second) + eps;
            int prev = owner[jbest];
            owner[jbest] = i;
            assignment[i] = jbest;
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned[nun++] = prev;
            }
        }
        total_it += it;
        if (nun > 0) incomplete = true;
        if (eps <= eps_final * 1.0001) {
            if (incomplete) total_it = -total_it;
            break;
        }
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_it;
}
