#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <iostream>

// Transportation network simplex, Dantzig pivot (most negative reduced cost).
// Returns 0 on success. Fills G as dense row-major (only for small n tests).
struct Solver {
    int n, m;
    const double* M;
    std::vector<double> flow; // n*m, 0 if nonbasic
    std::vector<char> basic;
    std::vector<int> parent; // tree parent node, nodes 0..n-1 rows, n..n+m-1 cols
    std::vector<int> depth;
    std::vector<int> mate; // for row node, basic col; unused
    // adjacency via basic edges stored as child lists
    std::vector<std::vector<int>> children;
    std::vector<double> u, v;

    Solver(const double* M_, int n_, int m_) : n(n_), m(m_), M(M_),
        flow(n_*m_, 0), basic(n_*m_, 0), parent(n_+m_, -1), depth(n_+m_, 0),
        children(n_+m_), u(n_, 0), v(m_, 0) {}

    inline int rc(int i) { return i; }
    inline int cc(int j) { return n + j; }
    inline double cost(int i, int j) const { return M[(size_t)i * m + j]; }
    inline int idx(int i, int j) const { return i * m + j; }

    void add_basic(int i, int j, double f) {
        int id = idx(i, j);
        basic[id] = 1;
        flow[id] = f;
    }

    void nw_init(const double* a, const double* b) {
        std::vector<double> aa(a, a+n), bb(b, b+m);
        int i = 0, j = 0;
        int need = n + m - 1;
        int have = 0;
        while (have < need && i < n && j < m) {
            double take = std::min(aa[i], bb[j]);
            if (!basic[idx(i, j)]) { add_basic(i, j, take); ++have; }
            else flow[idx(i, j)] += take;
            aa[i] -= take; bb[j] -= take;
            bool rd = aa[i] <= 1e-12, cd = bb[j] <= 1e-12;
            if (rd && cd) {
                if (i < n-1 && j < m-1) {
                    ++i;
                    if (!basic[idx(i, j)] && have < need) { add_basic(i, j, 0.0); ++have; }
                    ++j;
                } else if (i < n-1) ++i;
                else if (j < m-1) ++j;
                else break;
            } else if (rd) ++i;
            else ++j;
        }
    }

    // build spanning tree rooted at row 0, children lists
    bool build_tree() {
        for (int i = 0; i < n + m; ++i) { children[i].clear(); parent[i] = -1; depth[i] = 0; }
        std::vector<std::vector<int>> adj(n + m);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                if (basic[idx(i, j)]) {
                    adj[i].push_back(n + j);
                    adj[n + j].push_back(i);
                }
        std::vector<int> stack = {0};
        parent[0] = -2;
        while (!stack.empty()) {
            int node = stack.back(); stack.pop_back();
            for (int nei : adj[node]) {
                if (parent[nei] == -1) {
                    parent[nei] = node;
                    depth[nei] = depth[node] + 1;
                    children[node].push_back(nei);
                    stack.push_back(nei);
                }
            }
        }
        for (int i = 0; i < n + m; ++i) if (parent[i] == -1) return false;
        return true;
    }

    void compute_duals() {
        u[0] = 0;
        std::vector<int> stack = {0};
        std::vector<char> seen(n + m, 0);
        seen[0] = 1;
        while (!stack.empty()) {
            int node = stack.back(); stack.pop_back();
            for (int nei : children[node]) {
                if (node < n) {
                    // node row, nei col
                    int i = node, j = nei - n;
                    v[j] = cost(i, j) - u[i];
                } else {
                    int j = node - n, i = nei;
                    u[i] = cost(i, j) - v[j];
                }
                stack.push_back(nei);
            }
        }
    }

    // find most negative reduced cost
    bool find_enter(int& ei, int& ej, double& best) {
        best = -1e-12;
        ei = ej = -1;
        for (int i = 0; i < n; ++i) {
            double ui = u[i];
            const double* row = M + (size_t)i * m;
            for (int j = 0; j < m; ++j) {
                if (basic[idx(i, j)]) continue;
                double rc = row[j] - ui - v[j];
                if (rc < best) { best = rc; ei = i; ej = j; }
            }
        }
        return ei >= 0;
    }

    // path from node up to root
    void path_to_root(int node, std::vector<int>& out) {
        out.clear();
        while (node != -2) { out.push_back(node); node = parent[node]; }
    }

    bool pivot(int ei, int ej) {
        // cycle between row ei and col ej
        int rn = ei, cn = n + ej;
        std::vector<int> pr, pc;
        path_to_root(rn, pr);
        path_to_root(cn, pc);
        // find lca
        int a = (int)pr.size() - 1, b = (int)pc.size() - 1;
        while (a >= 0 && b >= 0 && pr[a] == pc[b]) { --a; --b; }
        // pr[a+1] == pc[b+1] is lca
        // cycle edges with sign. Entering edge +: flow row->col increases.
        // Walk from ei up to lca (these edges: leaving direction depends)
        // Represent cycle as list of (i,j,sign) sign -1 means decrease (candidate leave)
        struct E { int i, j, sgn; };
        std::vector<E> cyc;
        cyc.push_back({ei, ej, +1});
        // from row ei up to lca: edges (child,parent)
        // nodes pr[0]=ei, pr[1], ... pr[a] is last before lca, pr[a+1]=lca
        auto edge_of = [&](int child, int par, int sgn, std::vector<E>& out) {
            int i, j;
            if (child < n) { i = child; j = par - n; }
            else { i = par; j = child - n; }
            out.push_back({i, j, sgn});
        };
        // direction: after entering (row ei -> col ej) with +, we are at col ej and need to return to row ei via tree.
        // Simpler sign assignment: the cycle orientation increases entering.
        // Tree path from col node cn back to row node rn.
        // Build full node cycle: ei, then from cn up to lca, then from lca down to ei (reverse of pr).
        // Signs alternate starting with + on entering, so first tree edge (from cn to its direction toward rn) is -.
        int sgn = -1;
        // from cn up to lca (pc[0]=cn ... pc[b] child of lca)
        for (int t = 0; t <= b; ++t) {
            int child = pc[t];
            int par = (t == b) ? pc[b+1] : pc[t+1]; // parent toward root, but when t==b parent is lca = pc[b+1]
            // wait pc[b] 's parent is pc[b+1] which is lca. Yes if we stored parent chain.
            // pc is path to root: pc[t+1] is parent of pc[t]. So par = pc[t+1], and for t==b, pc[b+1] is lca. Good, loop t<=b uses pc[b+1].
            edge_of(child, pc[t+1], sgn, cyc);
            sgn = -sgn;
        }
        // now from lca down to ei: reverse pr from a down to 0
        // pr[a] 's parent is lca = pr[a+1]
        // walking down: from lca to pr[a] to pr[a-1] ... to pr[0]
        // edge between pr[t+1] (parent) and pr[t] (child), child is pr[t]
        for (int t = a; t >= 0; --t) {
            int child = pr[t];
            int par = pr[t+1];
            edge_of(child, par, sgn, cyc);
            sgn = -sgn;
        }
        // leaving: min flow among sgn -1, tie = first
        double theta = 1e300;
        int li = -1, lj = -1;
        for (auto& e : cyc) if (e.sgn < 0) {
            double f = flow[idx(e.i, e.j)];
            if (f < theta) { theta = f; li = e.i; lj = e.j; }
        }
        if (li < 0) return false;
        for (auto& e : cyc) {
            int id = idx(e.i, e.j);
            if (e.sgn > 0) flow[id] += theta;
            else flow[id] -= theta;
        }
        basic[idx(li, lj)] = 0;
        flow[idx(li, lj)] = 0;
        basic[idx(ei, ej)] = 1;
        return true;
    }

    int solve(const double* a, const double* b, int max_piv) {
        nw_init(a, b);
        int piv = 0;
        for (; piv < max_piv; ++piv) {
            if (!build_tree()) return -1;
            compute_duals();
            int ei, ej; double best;
            if (!find_enter(ei, ej, best)) return piv;
            if (!pivot(ei, ej)) return -2;
        }
        return -3;
    }
};

extern "C" int ns_solve(const double* a, const double* b, const double* M, int n, int m, double* G, int* pivots) {
    Solver s(M, n, m);
    int p = s.solve(a, b, 100000);
    *pivots = p;
    if (p < 0) return p;
    for (int i = 0; i < n * m; ++i) G[i] = s.flow[i] > 1e-14 ? s.flow[i] : 0.0;
    return 0;
}
