#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>

// Network simplex with candidate pricing and incremental tree (parent pointers + reroot).
struct Solver {
    int n, m, k;
    const double* M;
    const int* cand;
    std::vector<double> flow;
    std::vector<char> basic;
    std::vector<int> parent, depth, basic_col_of_parent_edge; // unused
    // For each node, the basic edge connecting to parent: peer index (col if node is row, row if node is col)
    std::vector<int> peer; // parent-edge other endpoint index in its own space
    std::vector<double> u, v;
    std::vector<int> pred_node; // temporary

    Solver(const double* M_, int n_, int m_, const int* cand_, int k_)
        : n(n_), m(m_), k(k_), M(M_), cand(cand_),
          flow((size_t)n_*m_, 0.0), basic((size_t)n_*m_, 0),
          parent(n_+m_, -1), depth(n_+m_, 0), peer(n_+m_, -1),
          u(n_, 0.0), v(m_, 0.0) {}

    inline double cost(int i, int j) const { return M[(size_t)i * m + j]; }
    inline size_t idx(int i, int j) const { return (size_t)i * m + j; }

    void nw_init(const double* a, const double* b) {
        std::vector<double> aa(a, a + n), bb(b, b + m);
        int i = 0, j = 0, need = n + m - 1, have = 0;
        while (have < need && i < n && j < m) {
            double take = std::min(aa[i], bb[j]);
            size_t id = idx(i, j);
            if (!basic[id]) { basic[id] = 1; flow[id] = take; ++have; }
            else flow[id] += take;
            aa[i] -= take; bb[j] -= take;
            bool rd = aa[i] <= 1e-12, cd = bb[j] <= 1e-12;
            if (rd && cd) {
                if (i < n - 1 && j < m - 1) {
                    ++i;
                    id = idx(i, j);
                    if (!basic[id] && have < need) { basic[id] = 1; flow[id] = 0; ++have; }
                    ++j;
                } else if (i < n - 1) ++i;
                else if (j < m - 1) ++j;
                else break;
            } else if (rd) ++i;
            else ++j;
        }
    }

    bool build_tree() {
        std::vector<std::vector<int>> adj(n + m);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                if (basic[idx(i, j)]) {
                    adj[i].push_back(n + j);
                    adj[n + j].push_back(i);
                }
        std::fill(parent.begin(), parent.end(), -1);
        parent[0] = -2;
        depth[0] = 0;
        std::vector<int> stack = {0};
        int seen = 1;
        while (!stack.empty()) {
            int node = stack.back(); stack.pop_back();
            for (int nei : adj[node]) if (parent[nei] == -1) {
                parent[nei] = node;
                depth[nei] = depth[node] + 1;
                if (node < n) peer[nei] = node;          // col's parent is row node=peer
                else peer[node] = nei;                    // wait, store peer of child
                // peer[child] = other endpoint index
                if (nei >= n) peer[nei] = node;           // child is col, peer row index = node
                else peer[nei] = node - n;                // child is row, peer col index = node-n
                stack.push_back(nei);
                ++seen;
            }
        }
        return seen == n + m;
    }

    void compute_duals() {
        u[0] = 0;
        std::vector<int> stack = {0};
        // children not stored; walk by scanning parent array once in increasing depth via stack of adjacency rebuild is costly.
        // Build children quickly from parent.
        std::vector<std::vector<int>> children(n + m);
        for (int i = 0; i < n + m; ++i) if (parent[i] >= 0) children[parent[i]].push_back(i);
        while (!stack.empty()) {
            int node = stack.back(); stack.pop_back();
            for (int nei : children[node]) {
                if (node < n) {
                    int i = node, j = nei - n;
                    v[j] = cost(i, j) - u[i];
                } else {
                    int j = node - n, i = nei;
                    u[i] = cost(i, j) - v[j];
                }
                stack.push_back(nei);
            }
        }
    }

    bool find_enter(int& ei, int& ej, bool full) {
        double best = -1e-12;
        ei = ej = -1;
        if (full || k <= 0) {
            for (int i = 0; i < n; ++i) {
                double ui = u[i];
                const double* row = M + (size_t)i * m;
                for (int j = 0; j < m; ++j) {
                    if (basic[idx(i, j)]) continue;
                    double rc = row[j] - ui - v[j];
                    if (rc < best) { best = rc; ei = i; ej = j; }
                }
            }
        } else {
            for (int i = 0; i < n; ++i) {
                double ui = u[i];
                const double* row = M + (size_t)i * m;
                const int* cs = cand + (size_t)i * k;
                for (int t = 0; t < k; ++t) {
                    int j = cs[t];
                    if (basic[idx(i, j)]) continue;
                    double rc = row[j] - ui - v[j];
                    if (rc < best) { best = rc; ei = i; ej = j; }
                }
            }
        }
        return ei >= 0;
    }

    void update_dual_subtree(int root_node, double delta_u_if_row) {
        // After pivot, duals change on one side of the cut. We'll just recompute all duals; n=600 is fine if tree walk is O(n).
        // This function unused; compute_duals is O(n).
    }

    bool pivot(int ei, int ej) {
        int cn = n + ej;
        // collect path nodes
        std::vector<int> pr, pc;
        for (int node = ei; node != -2; node = parent[node]) pr.push_back(node);
        for (int node = cn; node != -2; node = parent[node]) pc.push_back(node);
        int a = (int)pr.size() - 1, b = (int)pc.size() - 1;
        while (a >= 0 && b >= 0 && pr[a] == pc[b]) { --a; --b; }
        struct E { int i, j, sgn; };
        std::vector<E> cyc;
        cyc.push_back({ei, ej, +1});
        auto edge_of = [&](int child, int par, int sgn) {
            int i, j;
            if (child < n) { i = child; j = par - n; }
            else { i = par; j = child - n; }
            cyc.push_back({i, j, sgn});
        };
        int sgn = -1;
        for (int t = 0; t <= b; ++t) { edge_of(pc[t], pc[t + 1], sgn); sgn = -sgn; }
        for (int t = a; t >= 0; --t) { edge_of(pr[t], pr[t + 1], sgn); sgn = -sgn; }

        double theta = 1e300;
        int li = -1, lj = -1, leave_pos = -1;
        for (int t = 0; t < (int)cyc.size(); ++t) {
            if (cyc[t].sgn < 0) {
                double f = flow[idx(cyc[t].i, cyc[t].j)];
                if (f < theta) { theta = f; li = cyc[t].i; lj = cyc[t].j; leave_pos = t; }
            }
        }
        if (li < 0) return false;
        for (auto& e : cyc) {
            size_t id = idx(e.i, e.j);
            if (e.sgn > 0) flow[id] += theta;
            else flow[id] -= theta;
        }
        basic[idx(li, lj)] = 0;
        flow[idx(li, lj)] = 0;
        basic[idx(ei, ej)] = 1;

        // Update tree: remove leave edge, add enter edge. Reroot the detached subtree.
        // Identify which endpoint of leave edge is in the subtree not containing root.
        int leave_row_node = li;
        int leave_col_node = n + lj;
        // The child is the one whose parent is the other.
        int child, par;
        if (parent[leave_row_node] == leave_col_node) { child = leave_row_node; par = leave_col_node; }
        else if (parent[leave_col_node] == leave_row_node) { child = leave_col_node; par = leave_row_node; }
        else {
            // shouldn't happen
            return build_tree();
        }
        // Entering edge connects ei (row) and cn=n+ej (col). One of them is in detached subtree (child side), the other is on root side.
        // Reroot detached subtree so that the endpoint of entering edge inside it becomes connected to the outside endpoint.
        int in_sub, out_node;
        // Is ei in subtree of child?
        auto in_subtree = [&](int node, int subroot) {
            while (node != -2) {
                if (node == subroot) return true;
                node = parent[node];
            }
            return false;
        };
        bool ei_in = in_subtree(ei, child);
        if (ei_in) { in_sub = ei; out_node = cn; }
        else { in_sub = cn; out_node = ei; }

        // Reverse parent pointers from in_sub up to child (inclusive)
        int prev = out_node;
        int cur = in_sub;
        while (true) {
            int p = parent[cur];
            parent[cur] = prev;
            // depth fixed later
            if (cur == child) break;
            prev = cur;
            cur = p;
        }
        // fix depths in subtree of new child (which is in_sub, now parented to out_node)
        // BFS/stack from in_sub
        std::vector<int> stack = {in_sub};
        // We need children. Build adjacency of current parent links for subtree update only: scan all nodes whose ancestor is in_sub.
        // O(n) scan is fine.
        // First set depth of in_sub
        depth[in_sub] = depth[out_node] + 1;
        // Repeated relaxation: for nodes whose parent depth is known, set depth. Do a stack walk using parent inverse via a scan list.
        // Build list of nodes and process in a queue by finding children each time is O(n^2). Instead one pass collecting children arrays for all nodes O(n).
        std::vector<std::vector<int>> ch(n + m);
        for (int i = 0; i < n + m; ++i) if (parent[i] >= 0) ch[parent[i]].push_back(i);
        stack.clear();
        stack.push_back(in_sub);
        depth[in_sub] = depth[parent[in_sub]] + 1;
        while (!stack.empty()) {
            int node = stack.back(); stack.pop_back();
            for (int c : ch[node]) {
                depth[c] = depth[node] + 1;
                stack.push_back(c);
            }
        }
        return true;
    }

    int solve(const double* a, const double* b, int max_piv, bool do_final_full) {
        nw_init(a, b);
        if (!build_tree()) return -1;
        int piv = 0;
        bool full = (k <= 0);
        for (; piv < max_piv; ++piv) {
            compute_duals();
            int ei, ej;
            if (!find_enter(ei, ej, full)) {
                if (!full && do_final_full) { full = true; continue; }
                return piv;
            }
            if (!pivot(ei, ej)) return -2;
        }
        return -3;
    }
};

extern "C" int ns_solve3(const double* a, const double* b, const double* M, int n, int m,
                         const int* cand, int k, double* G, int* pivots, int final_full) {
    Solver s(M, n, m, cand, k);
    int p = s.solve(a, b, 500000, final_full != 0);
    *pivots = p;
    if (p < 0) return p;
    for (int i = 0; i < n * m; ++i) G[i] = s.flow[i] > 1e-14 ? s.flow[i] : 0.0;
    return 0;
}
