#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>

// Epsilon-scaling auction with a final eps < 1/(n+1) on integerized costs,
// which is exact for the assignment problem (Bertsekas).
// cost is float; we scale to integers internally.
extern "C" int auction_exact(const double* cost, int n, int* col_of_row, double scale) {
    // integer costs
    std::vector<long long> C((size_t)n * n);
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) {
        double v = cost[i] * scale;
        if (v < 0) v = 0;
        C[i] = (long long)(v + 0.5);
    }
    // prices in same integer units, but we keep them as long long and use eps = 1
    // For exactness with integer costs, eps < 1/n, so we scale prices by n and use eps_scaled = 1
    // Work in units of 1/n: price_real = price_num / n, eps = 1/(n+1) approx 1/n.
    // Use price as long long representing price * (n) , eps_units = 1, costs * n.
    long long S = n; // scale factor for fractional eps=1/n
    std::vector<long long> price(n, 0); // in units of 1/S
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);

    // epsilon scaling in units of 1/S: start large
    long long cmax = 0;
    for (auto c : C) if (c > cmax) cmax = c;
    long long eps = cmax * S / 4; // in 1/S units, corresponds to cmax/4
    if (eps < 1) eps = 1;
    int total_it = 0;
    const long long NEG = -(1LL << 62);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int it = 0;
        int max_iter = n * 400;
        while (nun > 0 && it < max_iter) {
            int i = unassigned[--nun];
            ++it;
            const long long* ci = C.data() + (size_t)i * n;
            int jbest = 0;
            long long best = NEG, second = NEG;
            for (int j = 0; j < n; ++j) {
                // value = -(cost)*S - price
                long long val = -ci[j] * S - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            long long inc = (best - second) + eps;
            price[jbest] += inc;
            int prev = owner[jbest];
            owner[jbest] = i;
            assignment[i] = jbest;
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned[nun++] = prev;
            }
        }
        total_it += it;
        if (eps == 1) break;
        eps /= 4;
        if (eps < 1) eps = 1;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_it;
}
