#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <omp.h>

// Parallel epsilon-scaling auction. Each bidder scans the price vector (read-only during scan)
// then updates one price. Parallelism over the scan of a single bidder doesn't help much;
// instead process a batch of unassigned bidders... auction is inherently sequential for price updates.
// Alternative: Jacobi auction - all unassigned bid simultaneously using same prices, then resolve conflicts.
// Gauss-Seidel is faster in iterations but sequential. Jacobi can be parallel and sometimes similar iteration count.

extern "C" int auction_jacobi(const double* cost, int n, double eps_final, int* col_of_row, int nthreads) {
    omp_set_num_threads(nthreads);
    std::vector<double> price(n, 0.0);
    std::vector<int> assignment(n, -1);
    std::vector<int> owner(n, -1);

    double cmax = 0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = std::max(cmax / 2.0, eps_final);

    std::vector<int> unassigned(n), bid_col(n);
    std::vector<double> bid_inc(n);
    int total_it = 0;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int it = 0;
        int max_rounds = n * 30;
        while (nun > 0 && it < max_rounds) {
            ++it;
            // each unassigned person computes bid in parallel
            #pragma omp parallel for schedule(static)
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                const double* ci = cost + (size_t)i * n;
                int jbest = 0;
                double best = -1e300, second = -1e300;
                for (int j = 0; j < n; ++j) {
                    double val = -ci[j] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                bid_col[i] = jbest;
                bid_inc[i] = (best - second) + eps;
            }
            // resolve: for each column, highest increment bidder wins (Jacobi)
            // To avoid races, sequential resolve (n is 600, cheap vs scan)
            std::vector<int> next_un;
            next_un.reserve(nun);
            std::vector<int> winner(n, -1);
            std::vector<double> bestinc(n, -1);
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                int j = bid_col[i];
                double inc = bid_inc[i];
                if (inc > bestinc[j]) { bestinc[j] = inc; winner[j] = i; }
            }
            std::vector<char> got(n, 0);
            for (int j = 0; j < n; ++j) if (winner[j] >= 0) {
                price[j] += bestinc[j];
                int i = winner[j];
                int prev = owner[j];
                owner[j] = i;
                assignment[i] = j;
                got[i] = 1;
                if (prev >= 0 && prev != i) {
                    assignment[prev] = -1;
                }
            }
            // anyone unassigned
            next_un.clear();
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) next_un.push_back(i);
            // also people who were displaced
            nun = (int)next_un.size();
            for (int t = 0; t < nun; ++t) unassigned[t] = next_un[t];
        }
        total_it += it;
        if (eps <= eps_final * 1.01) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_it;
}
