#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <thread>
#include <atomic>

// Gauss-Seidel auction but the price scan is the bottleneck and is single-bidder.
// Parallelize the scan of one bidder across threads using partial best/second.
struct Partial {
    int jbest;
    double best, second;
};

extern "C" int auction_par(const double* cost, int n, double eps_final, int* col_of_row, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);
    double cmax = 0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = std::max(cmax / 4.0, eps_final);

    int total_it = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int it = 0;
        int max_iter = n * 200;
        while (nun > 0 && it < max_iter) {
            int i = unassigned[--nun];
            ++it;
            const double* ci = cost + (size_t)i * n;
            // parallel partial reductions
            std::vector<Partial> parts(nthreads);
            std::vector<std::thread> threads;
            int chunk = (n + nthreads - 1) / nthreads;
            for (int t = 0; t < nthreads; ++t) {
                int lo = t * chunk, hi = std::min(n, lo + chunk);
                threads.emplace_back([&, t, lo, hi]() {
                    int jbest = lo;
                    double best = -1e300, second = -1e300;
                    for (int j = lo; j < hi; ++j) {
                        double val = -ci[j] - price[j];
                        if (val > best) { second = best; best = val; jbest = j; }
                        else if (val > second) second = val;
                    }
                    parts[t] = {jbest, best, second};
                });
            }
            for (auto& th : threads) th.join();
            int jbest = 0;
            double best = -1e300, second = -1e300;
            for (int t = 0; t < nthreads; ++t) {
                // merge: consider parts[t].best and parts[t].second
                auto consider = [&](double val, int j) {
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                };
                consider(parts[t].best, parts[t].jbest);
                consider(parts[t].second, -1);
            }
            price[jbest] += (best - second) + eps;
            int prev = owner[jbest];
            owner[jbest] = i;
            assignment[i] = jbest;
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned[nun++] = prev;
            }
        }
        total_it += it;
        if (eps <= eps_final * 1.01) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_it;
}
