#include <vector>
#include <cmath>
#include <cstdint>
#include <algorithm>
#include <thread>

extern "C" int auction_jacobi(const double* cost, int n, double eps_final, int* col_of_row, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> assignment(n, -1), owner(n, -1);
    double cmax = 0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = std::max(cmax / 2.0, eps_final);

    std::vector<int> bid_col(n);
    std::vector<double> bid_inc(n);
    std::vector<int> unassigned(n);
    int total_rounds = 0;

    auto bid_range = [&](int lo, int hi, const std::vector<int>& un, int nun) {
        for (int t = lo; t < hi; ++t) {
            int i = un[t];
            const double* ci = cost + (size_t)i * n;
            int jbest = 0;
            double best = -1e300, second = -1e300;
            for (int j = 0; j < n; ++j) {
                double val = -ci[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            bid_col[i] = jbest;
            bid_inc[i] = (best - second) + eps;
        }
    };

    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        int max_rounds = n * 20;
        while (nun > 0 && rounds < max_rounds) {
            ++rounds;
            // parallel bid computation
            int chunk = (nun + nthreads - 1) / nthreads;
            std::vector<std::thread> threads;
            for (int t = 0; t < nthreads; ++t) {
                int lo = t * chunk, hi = std::min(nun, lo + chunk);
                if (lo >= hi) break;
                threads.emplace_back(bid_range, lo, hi, std::ref(unassigned), nun);
            }
            for (auto& th : threads) th.join();

            std::vector<int> winner(n, -1);
            std::vector<double> bestinc(n, -1.0);
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                int j = bid_col[i];
                double inc = bid_inc[i];
                if (inc > bestinc[j]) { bestinc[j] = inc; winner[j] = i; }
            }
            for (int j = 0; j < n; ++j) if (winner[j] >= 0) {
                price[j] += bestinc[j];
                int i = winner[j];
                int prev = owner[j];
                owner[j] = i;
                assignment[i] = j;
                if (prev >= 0 && prev != i) assignment[prev] = -1;
            }
            // rebuild unassigned: anyone with assignment < 0
            int nu = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[nu++] = i;
            nun = nu;
        }
        total_rounds += rounds;
        if (eps <= eps_final * 1.01) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total_rounds;
}
