#include <vector>
#include <thread>
#include <atomic>
#include <functional>
#include <cstdint>

// Persistent pool: workers spin on a generation counter.
struct Pool {
    int nthreads;
    std::vector<std::thread> threads;
    std::atomic<int> epoch{0};
    std::atomic<int> done{0};
    std::atomic<bool> stop{false};
    // job: function pointer + range
    void (*fn)(int, int, void*) = nullptr;
    void* ctx = nullptr;
    int n = 0;

    Pool(int nt) : nthreads(nt) {
        for (int t = 0; t < nthreads; ++t) {
            threads.emplace_back([this, t]() {
                int seen = 0;
                while (!stop.load(std::memory_order_relaxed)) {
                    int e = epoch.load(std::memory_order_acquire);
                    if (e == seen) {
                        // spin
                        continue;
                    }
                    seen = e;
                    if (stop.load()) break;
                    int chunk = (n + nthreads - 1) / nthreads;
                    int lo = t * chunk, hi = std::min(n, lo + chunk);
                    if (lo < hi && fn) fn(lo, hi, ctx);
                    done.fetch_add(1, std::memory_order_release);
                }
            });
        }
    }
    void run(void (*f)(int, int, void*), void* c, int nn) {
        fn = f; ctx = c; n = nn;
        done.store(0, std::memory_order_relaxed);
        epoch.fetch_add(1, std::memory_order_release);
        while (done.load(std::memory_order_acquire) < nthreads) {}
    }
    ~Pool() {
        stop.store(true);
        epoch.fetch_add(1, std::memory_order_release);
        for (auto& th : threads) th.join();
    }
};

struct Ctx {
    const double* cost;
    const double* price;
    int* bid_col;
    double* bid_inc;
    const int* unassigned;
    int n;
    double eps;
};

void bid_job(int lo, int hi, void* vctx) {
    Ctx* c = (Ctx*)vctx;
    int n = c->n;
    for (int t = lo; t < hi; ++t) {
        int i = c->unassigned[t];
        const double* ci = c->cost + (size_t)i * n;
        int jbest = 0;
        double best = -1e300, second = -1e300;
        const double* price = c->price;
        for (int j = 0; j < n; ++j) {
            double val = -ci[j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
        c->bid_col[i] = jbest;
        c->bid_inc[i] = (best - second) + c->eps;
    }
}

static Pool* gpool = nullptr;

extern "C" void pool_init(int nt) {
    if (gpool) delete gpool;
    gpool = new Pool(nt);
}
extern "C" void pool_close() {
    delete gpool; gpool = nullptr;
}

extern "C" int auction_pool(const double* cost, int n, double eps_final, int* col_of_row) {
    std::vector<double> price(n, 0.0);
    std::vector<int> assignment(n, -1), owner(n, -1);
    std::vector<int> bid_col(n), unassigned(n);
    std::vector<double> bid_inc(n);
    double cmax = 0;
    for (size_t i = 0, N = (size_t)n * n; i < N; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = std::max(cmax / 2.0, eps_final);
    int total = 0;
    Ctx ctx;
    ctx.cost = cost; ctx.n = n;
    ctx.bid_col = bid_col.data(); ctx.bid_inc = bid_inc.data();
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        ctx.eps = eps;
        ctx.price = price.data();
        ctx.unassigned = unassigned.data();
        while (nun > 0 && rounds < n * 20) {
            ++rounds;
            gpool->run(bid_job, &ctx, nun);
            std::vector<int> winner(n, -1);
            std::vector<double> bestinc(n, -1.0);
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                int j = bid_col[i];
                if (bid_inc[i] > bestinc[j]) { bestinc[j] = bid_inc[i]; winner[j] = i; }
            }
            for (int j = 0; j < n; ++j) if (winner[j] >= 0) {
                price[j] += bestinc[j];
                int i = winner[j];
                int prev = owner[j];
                owner[j] = i;
                assignment[i] = j;
                if (prev >= 0 && prev != i) assignment[prev] = -1;
            }
            int nu = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[nu++] = i;
            nun = nu;
            ctx.price = price.data();
            ctx.unassigned = unassigned.data();
        }
        total += rounds;
        if (eps <= eps_final * 1.01) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
        ctx.eps = eps;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total;
}
