                    int lo = t * chunk, hi = std::min(n, lo + chunk);
                    if (lo < hi && fn) fn(lo, hi, ctx);
                    done.fetch_add(1, std::memory_order_release);
                }
            });
        }
    }
    void run(void (*f)(int, int, void*), void* c, int nn) {
        fn = f; ctx = c; n = nn;
        done.store(0, std::memory_order_relaxed);
        epoch.fetch_add(1, std::memory_order_release);
        while (done.load(std::memory_order_acquire) < nthreads) {}
    }
    ~Pool() {
        stop.store(true);
        epoch.fetch_add(1, std::memory_order_release);
        for (auto& th : threads) th.join();
    }
};

struct Ctx {
    const double* benefit; // n*k, already negated distances? we'll store -dist
    const int* idxs;       // n*k
    const double* price;
    int* bid_col;
    double* bid_inc;
    const int* unassigned;
    int n, k;
    double eps;
};

void bid_job(int lo, int hi, void* v) {
    Ctx* c = (Ctx*)v;
    int k = c->k;
    const double* price = c->price;
    for (int t = lo; t < hi; ++t) {
        int i = c->unassigned[t];
        const double* b = c->benefit + (size_t)i * k;
        const int* js = c->idxs + (size_t)i * k;
        int jbest = js[0];
        double best = -1e300, second = -1e300;
        for (int t2 = 0; t2 < k; ++t2) {
            double val = b[t2] - price[js[t2]];
            if (val > best) { second = best; best = val; jbest = js[t2]; }
            else if (val > second) second = val;
        }
        c->bid_col[i] = jbest;
        c->bid_inc[i] = (best - second) + c->eps;
    }
}

static Pool* gpool = nullptr;
extern "C" void pool_init(int nt) { if (gpool) delete gpool; gpool = new Pool(nt); }
extern "C" void pool_close() { delete gpool; gpool = nullptr; }

extern "C" int auction_knn(const double* benefit, const int* idxs, int n, int k,
                           double eps_final, int* col_of_row) {
    std::vector<double> price(n, 0.0);
    std::vector<int> assignment(n, -1), owner(n, -1);
    std::vector<int> bid_col(n), unassigned(n);
    std::vector<double> bid_inc(n);
    double bmax = -1e300;
    for (size_t i = 0, N = (size_t)n * k; i < N; ++i) if (benefit[i] > bmax) bmax = benefit[i];
    // benefit is -dist, so range is about cmax
    double cmax = -bmax; // rough
    if (cmax < 1e-6) cmax = 1;
    double eps = std::max(cmax / 8.0, eps_final);
    Ctx ctx;
    ctx.benefit = benefit; ctx.idxs = idxs; ctx.n = n; ctx.k = k;
    ctx.bid_col = bid_col.data(); ctx.bid_inc = bid_inc.data();
    int total = 0;
    while (true) {
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        int nun = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int rounds = 0;
        ctx.eps = eps;
        ctx.price = price.data();
        ctx.unassigned = unassigned.data();
        while (nun > 0 && rounds < n * 40) {
            ++rounds;
            gpool->run(bid_job, &ctx, nun);
            std::vector<int> winner(n, -1);
            std::vector<double> bestinc(n, -1.0);
            for (int t = 0; t < nun; ++t) {
                int i = unassigned[t];
                int j = bid_col[i];
                if (bid_inc[i] > bestinc[j]) { bestinc[j] = bid_inc[i]; winner[j] = i; }
            }
            for (int j = 0; j < n; ++j) if (winner[j] >= 0) {
                price[j] += bestinc[j];
                int i = winner[j];
                int prev = owner[j];
                owner[j] = i;
                assignment[i] = j;
                if (prev >= 0 && prev != i) assignment[prev] = -1;
            }
            int nu = 0;
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) unassigned[nu++] = i;
            nun = nu;
            ctx.price = price.data();
            ctx.unassigned = unassigned.data();
        }
        total += rounds;
        if (eps <= eps_final * 1.01) break;
        eps *= 0.5;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    return total;
}
